<template><section aria-label="图片压缩工具"><p class="tool-note">本地批量压缩，不上传图片。支持 PNG / JPEG / WebP / BMP / AVIF；一次最多 10 张，总计 60 MB，单张 20 MB、1600 万像素。导出会移除原始元数据；动图仅处理首帧，请保留原文件。</p><label class="tool-label">选择待压缩图片<input ref="fileInput" type="file" multiple accept="image/png,image/jpeg,image/webp,image/bmp,image/avif" aria-label="选择待压缩图片" :disabled="processing" @change="selectFiles" /></label><fieldset class="compression-settings" :disabled="processing"><label>输出格式<select v-model="format" aria-label="压缩输出格式"><option value="image/webp">WebP</option><option value="image/jpeg">JPEG</option><option value="image/png">PNG</option></select></label><label>压缩质量 {{quality}}%<input v-model.number="quality" type="range" min="10" max="100" :disabled="format==='image/png'" aria-label="压缩质量" /></label><label>最长边<select v-model.number="maxEdge" aria-label="压缩最长边"><option :value="8192">最大 8192 px（不放大）</option><option :value="2560">2560 px</option><option :value="1920">1920 px</option><option :value="1280">1280 px</option><option :value="800">800 px</option></select></label></fieldset><p class="tool-note">JPEG 的透明区域填充白色；WebP / PNG 保留透明度。PNG 为无损编码，质量滑块不生效。体积不一定变小，结果会如实显示；请自行保留原图。</p><div class="tool-actions"><button type="button" :disabled="!files.length||processing" @click="compress">{{processing?`压缩中 ${finished}/${files.length}`:'开始压缩'}}</button><button type="button" :disabled="!files.length" @click="clear">清空图片</button></div><p role="status">{{message}}</p><p v-if="results.length" class="tool-note">已完成 {{results.length}} 张：{{formatBytes(totalBefore)}} → {{formatBytes(totalAfter)}}，{{savings(totalBefore,totalAfter)}}。</p><div class="compression-list"><article v-for="(row,index) in files" :key="row.id" class="compression-card"><h3 :title="row.file.name">{{row.file.name}}</h3><div class="compression-previews"><figure><img :src="row.originalUrl" alt="原始图片预览" /><figcaption>原图 {{formatBytes(row.file.size)}}</figcaption></figure><figure><img v-if="row.outputUrl" :src="row.outputUrl" alt="压缩后图片预览" /><span v-else class="compression-placeholder">{{row.status==='working'?'处理中…':row.status==='error'?'处理失败':'等待压缩'}}</span><figcaption>{{row.blob?`结果 ${formatBytes(row.blob.size)}`:'压缩结果'}}</figcaption></figure></div><p v-if="row.blob">{{row.width}} × {{row.height}} · {{row.blob.type.split('/')[1].toUpperCase()}} · {{savings(row.file.size,row.blob.size)}}</p><p v-if="row.error" class="tool-error" role="alert">{{row.error}}</p><button v-if="row.blob" type="button" :aria-label="`下载压缩图片 ${index+1}`" @click="download(row)">下载处理结果</button><button v-if="row.blob&&row.blob.size>=row.file.size" type="button" @click="downloadOriginal(row)">下载原图</button></article></div></section></template>
<script>
import {compressImageFile,compressionSavings} from '../../utils/image-compression.mjs';
import {formatBytes,downloadBlob} from '../../utils/utility-tools.mjs';
export default{name:'ImageCompressionTool',data:()=>({files:[],format:'image/webp',quality:80,maxEdge:1920,processing:false,finished:0,message:'',request:0,nextId:0}),computed:{results(){return this.files.filter(r=>r.blob);},totalBefore(){return this.results.reduce((s,r)=>s+r.file.size,0);},totalAfter(){return this.results.reduce((s,r)=>s+r.blob.size,0);}},beforeUnmount(){this.clear();},methods:{formatBytes,savings(before,after){const n=compressionSavings(before,after);return n>=0?`减少 ${n.toFixed(1)}%`:`体积增加 ${(-n).toFixed(1)}%`;},selectFiles(event){const chosen=Array.from(event.target.files||[]);event.target.value='';if(!chosen.length)return;if(chosen.length>10||chosen.reduce((s,f)=>s+f.size,0)>60*1024*1024){this.message='一次最多选择 10 张，总大小不超过 60 MB';return;}this.clear();this.files=chosen.map(file=>({id:++this.nextId,file,originalUrl:URL.createObjectURL(file),outputUrl:'',blob:null,status:'pending',error:'',width:0,height:0,extension:''}));this.message=`已选择 ${chosen.length} 张图片，请设置参数后开始压缩`;},clear(){this.request++;this.files.forEach(r=>{URL.revokeObjectURL(r.originalUrl);if(r.outputUrl)URL.revokeObjectURL(r.outputUrl);});this.files=[];this.processing=false;this.finished=0;this.message='';},async compress(){const request=++this.request;this.processing=true;this.finished=0;this.message='正在本地处理图片…';const options={format:this.format,quality:this.quality,maxEdge:this.maxEdge};try{for(const row of this.files){if(request!==this.request)return;if(row.outputUrl)URL.revokeObjectURL(row.outputUrl);row.outputUrl='';row.blob=null;row.error='';row.status='working';try{const result=await compressImageFile(row.file,options);if(request!==this.request)return;Object.assign(row,result,{outputUrl:URL.createObjectURL(result.blob),status:'done'});}catch(e){if(request!==this.request)return;row.status='error';row.error=e.message||'图片处理失败';}this.finished++;}if(request===this.request)this.message=`处理完成：成功 ${this.results.length} 张，失败 ${this.files.length-this.results.length} 张`;}finally{if(request===this.request)this.processing=false;}},download(row){const base=row.file.name.replace(/\.[^.]+$/,'').replace(/[<>:"/\\|?*]/g,'_')||'image';downloadBlob(row.blob,`${base}-compressed.${row.extension}`);},downloadOriginal(row){downloadBlob(row.file,row.file.name);}}};
</script>
<style scoped>
.compression-settings{display:flex;gap:16px;flex-wrap:wrap;margin:14px 0;padding:0;border:0}.compression-settings label{display:flex;flex-direction:column;gap:8px;font-size:12px;min-width:130px}.compression-list{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px;margin:16px 0}.compression-card{min-width:0;border:1px solid var(--el-border-color-light);border-radius:3px;padding:14px;background:var(--el-fill-color-blank)}.compression-card h3{font-size:13px;margin:0 0 12px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.compression-previews{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.compression-previews figure{min-width:0;margin:0}.compression-previews img,.compression-placeholder{display:block;box-sizing:border-box;width:100%;height:140px;object-fit:contain;border:1px solid var(--el-border-color-light);background:repeating-conic-gradient(var(--el-fill-color-light) 0 25%,var(--el-fill-color-blank) 0 50%) 0/16px 16px}.compression-placeholder{display:flex;align-items:center;justify-content:center;font-size:12px;color:var(--el-text-color-secondary)}figcaption,.compression-card p{font-size:11px;line-height:1.7;margin:7px 0;color:var(--el-text-color-secondary)}.compression-card button{margin:5px 6px 0 0}@media(max-width:700px){.compression-list{grid-template-columns:minmax(0,1fr)}.compression-settings{gap:12px}.compression-previews img,.compression-placeholder{height:110px}}
</style>
